k=json.load(open('known-forms.json'))
out=dict(sorted(G.items()))
out["__broaden__"]={f:k[f]+s for f,s in sorted(B.items())}
json.dump(out,open('gloss.json','w'),ensure_ascii=False,indent=1)
nov=json.load(open('novel-forms.json'))
g=json.load(open('gloss.json'))
print('missing',[w for w in nov if w not in g],'extra',[w for w in g if w!='__broaden__' and w not in nov])
print('long',[(w,len(v)) for w,v in list(g.items())[:-1]+list(g['__broaden__'].items()) if w!='__broaden__' and len(v)>=230])
print(len(g)-1,len(g['__broaden__']))
